// Claude's review tests for A33 (change a real response). agy: do not edit this file.
import { describe, expect, it } from 'vitest';
import { exportProject, parseProjectFile } from './exportFile';
import { applyPatch, patchSummary } from './patchResponse';
import { newProject, type Mock } from './types';

const real = (body: unknown, status = 200, headers: Record<string, string> = { 'content-type': 'application/json', 'content-length': '99' }) =>
  ({ status, headers, body: typeof body === 'string' ? body : JSON.stringify(body) });

describe('applyPatch', () => {
  it('sets and removes by dot path, with array indexes and *', () => {
    const r = applyPatch(real({ user: { name: 'A', flags: { beta: true } }, items: [{ price: 1 }, { price: 2 }] }), {
      set: [{ path: 'user.flags.beta', value: 'false' }, { path: 'items.*.price', value: '0' }, { path: 'items.1.tag', value: '"sale"' }],
      remove: ['user.name'],
    });
    expect(JSON.parse(r.body)).toEqual({ user: { flags: { beta: false } }, items: [{ price: 0 }, { price: 0, tag: 'sale' }] });
  });
  it('makes missing objects on the way, and keeps text that is not JSON as a string', () => {
    const r = applyPatch(real({ a: 1 }), { set: [{ path: 'b.c.d', value: 'hello there' }, { path: 'e', value: '{"x":[1]}' }] });
    expect(JSON.parse(r.body)).toEqual({ a: 1, b: { c: { d: 'hello there' } }, e: { x: [1] } });
  });
  it('runs set and remove in order: sets first, then removes', () => {
    const r = applyPatch(real({ a: 1 }), { set: [{ path: 'b', value: '2' }], remove: ['b', 'a', 'missing.deep'] });
    expect(JSON.parse(r.body)).toEqual({});
  });
  it('changes the status and headers; header names lower-cased; content-length dropped', () => {
    const r = applyPatch(real({ a: 1 }), { status: 503, headers: { 'X-Patched': '1', 'Content-Type': 'application/problem+json' } });
    expect(r.status).toBe(503);
    expect(r.headers).toEqual({ 'content-type': 'application/problem+json', 'x-patched': '1' });
    expect(JSON.parse(r.body)).toEqual({ a: 1 });
  });
  it('a body that is not JSON keeps its text; status and headers still apply', () => {
    const r = applyPatch(real('plain text', 200, { 'content-type': 'text/plain' }), { status: 201, set: [{ path: 'a', value: '1' }] });
    expect(r).toEqual({ status: 201, headers: { 'content-type': 'text/plain' }, body: 'plain text' });
  });
  it('a path through a value that is not an object is left alone', () => {
    const r = applyPatch(real({ a: 5, list: [1] }), { set: [{ path: 'a.b', value: '1' }, { path: 'list.9.x', value: '1' }] });
    expect(JSON.parse(r.body)).toEqual({ a: 5, list: [1] });
  });
  it('setting an array item past the end, as the last step, changes nothing', () => {
    const r = applyPatch(real({ list: [1, 2] }), { set: [{ path: 'list.5', value: '9' }, { path: 'list.1', value: '7' }] });
    expect(JSON.parse(r.body)).toEqual({ list: [1, 7] });
  });
  it('an empty patch gives the real response back, without content-length', () => {
    expect(applyPatch(real({ a: 1 }), {})).toEqual({ status: 200, headers: { 'content-type': 'application/json' }, body: '{"a":1}' });
  });
  it('never touches __proto__', () => {
    const r = applyPatch(real({}), { set: [{ path: '__proto__.polluted', value: 'true' }] });
    expect(({} as Record<string, unknown>).polluted).toBeUndefined();
    expect(JSON.parse(r.body)).toEqual({});
  });
});

describe('patchSummary', () => {
  it('lists the changes in words', () => {
    expect(patchSummary({ status: 503, headers: { 'x-a': '1' }, set: [{ path: 'user.beta', value: 'false' }], remove: ['token'] })).toEqual([
      'Status 503',
      'Header x-a: 1',
      'Set user.beta = false',
      'Remove token',
    ]);
    expect(patchSummary({})).toEqual(['No changes: the real response as it is']);
  });
});

describe('files carry patch', () => {
  function file(patch: unknown): string {
    const p = newProject('p', 'http://a.test');
    const m: Mock = {
      id: 'm', enabled: true, method: 'GET', urlPattern: '/x', source: 'manual', createdAt: 0,
      response: { status: 200, headers: {}, body: '', bodyEncoding: 'text', delayMs: 0 }, reply: 'patch', patch: patch as Mock['patch'],
    };
    p.scenarios[0]!.mocks.push(m);
    return exportProject(p);
  }
  it('round-trips, and rejects a bad patch', () => {
    const patch = { status: 503, headers: { 'x-a': '1' }, set: [{ path: 'a', value: '1' }], remove: ['b'] };
    const r = parseProjectFile(file(patch));
    expect(r.ok && r.project.scenarios[0]!.mocks[0]!.patch).toEqual(patch);
    expect(r.ok && r.project.scenarios[0]!.mocks[0]!.reply).toBe('patch');
    expect(parseProjectFile(file({ status: 'x' })).ok).toBe(false);
    expect(parseProjectFile(file({ set: [{ path: 1 }] })).ok).toBe(false);
    expect(parseProjectFile(file({ remove: 'a' })).ok).toBe(false);
  });
});
